Code <pre><code>-- Création des types enum
CREATE TYPE type_vehicule AS ENUM ('bus', 'metro', 'tramway');
CREATE TYPE type_ligne AS ENUM ('bus', 'metro', 'tramway');
CREATE TYPE type_jour AS ENUM ('ouvre', 'samedi', 'dimanche', 'ferie');
CREATE TYPE type_titre AS ENUM ('unitaire', 'carnet10', 'mensuel', 'annuel');
CREATE TYPE type_installation AS ENUM ('abri', 'banc', 'distributeur', 'panneau_info');

-- Création des tables
CREATE TABLE Ligne (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero VARCHAR(20) UNIQUE NOT NULL,
    nom VARCHAR(100) NOT NULL,
    type type_ligne NOT NULL
);

CREATE TABLE Vehicule (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero_identification VARCHAR(50) UNIQUE NOT NULL,
    capacite_passagers INTEGER NOT NULL,
    date_mise_en_service DATE NOT NULL,
    type type_vehicule NOT NULL,
    ligne_id INTEGER NOT NULL REFERENCES Ligne(id)
);

CREATE TABLE Arret (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nom VARCHAR(100) NOT NULL,
    adresse TEXT,
    coordonnees_geo VARCHAR(50)
);

CREATE TABLE LigneArret (
    ligne_id INTEGER REFERENCES Ligne(id),
    arret_id INTEGER REFERENCES Arret(id),
    ordre INTEGER NOT NULL,
    PRIMARY KEY (ligne_id, arret_id)
);

CREATE TABLE Conducteur (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero_employe VARCHAR(50) UNIQUE NOT NULL,
    nom VARCHAR(100) NOT NULL,
    prenom VARCHAR(100) NOT NULL,
    date_embauche DATE NOT NULL
);

CREATE TABLE Horaire (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    jour_semaine type_jour NOT NULL,
    heure_passage TIME NOT NULL,
    ligne_id INTEGER NOT NULL REFERENCES Ligne(id),
    arret_id INTEGER NOT NULL REFERENCES Arret(id)
);

CREATE TABLE TitreTransport (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    type type_titre NOT NULL,
    prix DECIMAL(10, 2) NOT NULL,
    duree_validite INTEGER NOT NULL
);

CREATE TABLE Passager (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero_client VARCHAR(50) UNIQUE NOT NULL,
    nom VARCHAR(100) NOT NULL,
    prenom VARCHAR(100) NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL
);

CREATE TABLE Frequentation (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    date DATE NOT NULL,
    heure TIME NOT NULL,
    passagers_montants INTEGER NOT NULL,
    passagers_descendants INTEGER NOT NULL,
    arret_id INTEGER NOT NULL REFERENCES Arret(id),
    vehicule_id INTEGER NOT NULL REFERENCES Vehicule(id)
);

CREATE TABLE Incident (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    date DATE NOT NULL,
    type VARCHAR(100) NOT NULL,
    duree_immobilisation INTEGER NOT NULL,
    vehicule_id INTEGER NOT NULL REFERENCES Vehicule(id)
);

CREATE TABLE Installation (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    type type_installation NOT NULL
);

CREATE TABLE ArretInstallation (
    arret_id INTEGER REFERENCES Arret(id),
    installation_id INTEGER REFERENCES Installation(id),
    PRIMARY KEY (arret_id, installation_id)
);

CREATE TABLE StationVelos (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre_places INTEGER NOT NULL,
    velos_disponibles INTEGER NOT NULL,
    arret_id INTEGER UNIQUE NOT NULL REFERENCES Arret(id)
);

CREATE TABLE ConducteurVehicule (
    conducteur_id INTEGER REFERENCES Conducteur(id),
    vehicule_id INTEGER REFERENCES Vehicule(id),
    PRIMARY KEY (conducteur_id, vehicule_id)
);

CREATE TABLE PassagerTitreTransport (
    passager_id INTEGER REFERENCES Passager(id),
    titre_transport_id INTEGER REFERENCES TitreTransport(id),
    date_achat DATE NOT NULL,
    PRIMARY KEY (passager_id, titre_transport_id)
);
</code></pre> Utilisation de l’IA <p>Page rédigée en partie avec l’aide d’un assistant IA. L’IA a été utilisée pour générer des  explications, des exemples et/ou des suggestions de structure. Toutes les informations ont  été vérifiées, éditées et complétées par l’auteur.</p>

Code <pre><code>-- Création des types enum
CREATE TYPE type_prestataire AS ENUM ('compagnie_aerienne', 'hotel', 'location_voiture');

-- Création des tables
CREATE TABLE Destination (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nom VARCHAR(100) NOT NULL,
    pays VARCHAR(100) NOT NULL,
    description TEXT
);

CREATE TABLE Client (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero_client VARCHAR(50) UNIQUE NOT NULL,
    nom VARCHAR(100) NOT NULL,
    prenom VARCHAR(100) NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    telephone VARCHAR(20)
);

CREATE TABLE Voyage (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code VARCHAR(50) UNIQUE NOT NULL,
    date_depart DATE NOT NULL,
    date_retour DATE NOT NULL,
    prix_base DECIMAL(10, 2) NOT NULL,
    nombre_max_participants INTEGER,
    destination_id INTEGER NOT NULL REFERENCES Destination(id)
);

CREATE TABLE Reservation (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    date_reservation DATE NOT NULL,
    client_id INTEGER NOT NULL REFERENCES Client(id),
    voyage_id INTEGER NOT NULL REFERENCES Voyage(id)
);

CREATE TABLE Prestataire (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nom VARCHAR(100) NOT NULL,
    adresse TEXT,
    numero_contact VARCHAR(20),
    type type_prestataire NOT NULL
);

CREATE TABLE Vol (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero_vol VARCHAR(20) NOT NULL,
    voyage_id INTEGER NOT NULL REFERENCES Voyage(id),
    prestataire_id INTEGER NOT NULL REFERENCES Prestataire(id)
);

CREATE TABLE Sejour (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    type_chambre VARCHAR(50) NOT NULL,
    voyage_id INTEGER NOT NULL REFERENCES Voyage(id),
    prestataire_id INTEGER NOT NULL REFERENCES Prestataire(id)
);

CREATE TABLE LocationVoiture (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    categorie_voiture VARCHAR(50) NOT NULL,
    voyage_id INTEGER NOT NULL REFERENCES Voyage(id),
    prestataire_id INTEGER NOT NULL REFERENCES Prestataire(id)
);

CREATE TABLE Option (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nom VARCHAR(100) NOT NULL,
    description TEXT,
    prix DECIMAL(10, 2) NOT NULL
);

CREATE TABLE VoyageOption (
    voyage_id INTEGER REFERENCES Voyage(id),
    option_id INTEGER REFERENCES Option(id),
    PRIMARY KEY (voyage_id, option_id)
);

CREATE TABLE AgentVoyage (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero_employe VARCHAR(50) UNIQUE NOT NULL,
    nom VARCHAR(100) NOT NULL,
    prenom VARCHAR(100) NOT NULL,
    specialite VARCHAR(100)
);

CREATE TABLE Avis (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    note INTEGER CHECK (note BETWEEN 1 AND 5),
    commentaire TEXT,
    client_id INTEGER NOT NULL REFERENCES Client(id),
    voyage_id INTEGER NOT NULL REFERENCES Voyage(id)
);

CREATE TABLE PointsFidelite (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    points INTEGER NOT NULL,
    client_id INTEGER NOT NULL REFERENCES Client(id),
    voyage_id INTEGER NOT NULL REFERENCES Voyage(id)
);

CREATE TABLE VoyagePersonnalise (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    client_id INTEGER NOT NULL REFERENCES Client(id)
);

CREATE TABLE VoyagePersonnaliseVol (
    voyage_personnalise_id INTEGER REFERENCES VoyagePersonnalise(id),
    vol_id INTEGER REFERENCES Vol(id),
    PRIMARY KEY (voyage_personnalise_id, vol_id)
);

CREATE TABLE VoyagePersonnaliseSejour (
    voyage_personnalise_id INTEGER REFERENCES VoyagePersonnalise(id),
    sejour_id INTEGER REFERENCES Sejour(id),
    PRIMARY KEY (voyage_personnalise_id, sejour_id)
);

CREATE TABLE VoyagePersonnaliseLocationVoiture (
    voyage_personnalise_id INTEGER REFERENCES VoyagePersonnalise(id),
    location_voiture_id INTEGER REFERENCES LocationVoiture(id),
    PRIMARY KEY (voyage_personnalise_id, location_voiture_id)
);

CREATE TABLE VoyagePersonnaliseOption (
    voyage_personnalise_id INTEGER REFERENCES VoyagePersonnalise(id),
    option_id INTEGER REFERENCES Option(id),
    PRIMARY KEY (voyage_personnalise_id, option_id)
);

CREATE TABLE Paiement (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    date DATE NOT NULL,
    montant DECIMAL(10, 2) NOT NULL,
    mode_paiement VARCHAR(50) NOT NULL,
    reservation_id INTEGER NOT NULL REFERENCES Reservation(id)
);

CREATE TABLE VoyageOption (
    voyage_id INTEGER REFERENCES Voyage(id),
    option_id INTEGER REFERENCES Option(id),
    PRIMARY KEY (voyage_id, option_id)
);
</code></pre> Utilisation de l’IA <p>Page rédigée en partie avec l’aide d’un assistant IA. L’IA a été utilisée pour générer des  explications, des exemples et/ou des suggestions de structure. Toutes les informations ont  été vérifiées, éditées et complétées par l’auteur.</p>
